# 수치 자료는 모두 「가상 자료」로 밝혔고, 계산 문항은 아래에서 파이썬으로 다시 계산해 assert 로 확인한다.
# 사실(협약 연도·기관 이름 등)은 교과서 수준에서 확실한 것만 쓴다. 그림·그래프는 말과 값 목록으로 서술한다.
