Q(T, 3, '같은 위도에 있고 해발 고도가 비슷한 두 도시 A, B의 월평균 기온(가상 자료)이다. 두 도시 모두 1월이 가장 춥고 7월이 가장 덥다.\n\n'
  '· A: 1월 −12 ℃, 7월 22 ℃\n· B: 1월 2 ℃, 7월 18 ℃\n\n이에 대한 설명으로 가장 적절한 것은?',
  'B는 A보다 바다의 영향을 많이 받는 해안 지역일 가능성이 크다.',
  ['A의 기온 연교차는 22 ℃이다.',
   'A는 B보다 바다의 영향을 많이 받는 해안 지역일 가능성이 크다.',
   '두 도시의 기온 차이는 주로 위도 차이 때문이다.',
   'B의 기온 연교차는 A의 기온 연교차보다 크다.'],
  ['기온 연교차(최난월 − 최한월)는 A가 22 − (−12) = 34 ℃, B가 18 − 2 = 16 ℃이다.',
   '물은 비열이 커서 바다와 가까운 곳은 여름에 덜 덥고 겨울에 덜 추워 연교차가 작다. 따라서 연교차가 작은 B가 해안 지역일 가능성이 크고, A는 내륙 지역일 가능성이 크다.',
   '두 도시는 위도와 해발 고도가 비슷하므로 차이는 수륙 분포의 영향으로 보는 것이 알맞다.'])

eq(26 - 0.6 * 2500 / 100, 11)
Q(T, 3, '적도 부근의 해안 도시 P(해발 0 m)의 연평균 기온은 26 ℃이다. P와 위도가 거의 같고 해발 2500 m에 있는 고산 도시 Q의 연평균 기온은 약 몇 ℃인가? (단, 기온은 높이 100 m 올라갈 때마다 0.6 ℃씩 낮아지며, 다른 조건은 무시한다.)',
  '11 ℃', ['24.5 ℃', '41 ℃', '26 ℃', '15 ℃'],
  ['높이 차는 2500 m이고, 100 m마다 0.6 ℃씩 낮아지므로 기온 차는 25 × 0.6 = 15 ℃이다.',
   'Q의 연평균 기온은 26 − 15 = 11 ℃이다. 적도 부근이라도 고산 지역은 서늘한 기후가 나타난다.',
   '15 ℃는 기온 차를 답으로 쓴 것이고, 41 ℃는 빼야 할 값을 더한 것이며, 24.5 ℃는 100 m를 1000 m로 잘못 보고 계산한 값이다.'])

Q(T, 4, '북위 약 50°에서 한 대륙의 서쪽 해안에 있는 도시 P와 동쪽 해안에 있는 도시 Q의 자료(가상 자료)이다.\n\n'
  '· P: 1월 평균 기온 5 ℃, 7월 평균 기온 17 ℃, 강수가 연중 고른 편\n'
  '· Q: 1월 평균 기온 −12 ℃, 7월 평균 기온 20 ℃\n'
  '· 이 위도대에는 서쪽에서 동쪽으로 부는 편서풍이 우세하고, P 앞바다에는 난류가 흐른다.\n\n'
  '이에 대한 해석으로 가장 적절한 것은?',
  'P는 난류 위를 지나온 바다의 공기가 편서풍을 타고 들어와 겨울이 온화하고 기온 연교차가 작다.',
  ['P는 무역풍의 영향을 받아 겨울이 온화하다.',
   'Q는 P보다 바다의 영향을 많이 받아 기온 연교차가 작다.',
   'P의 기온 연교차는 Q보다 크다.',
   '두 도시의 겨울 기온 차이는 위도 차이 때문이다.'],
  ['기온 연교차는 P가 17 − 5 = 12 ℃, Q가 20 − (−12) = 32 ℃로 P가 훨씬 작다.',
   'P는 편서풍의 바람받이인 대륙 서안에 있어, 난류 위를 지나며 데워진 바다 공기의 영향을 연중 받는다. 그래서 겨울이 온화하고 연교차가 작다.',
   'Q는 대륙을 지나온 바람의 영향을 받아 연교차가 크다. 두 도시는 위도가 같으므로 위도 차이로 설명할 수 없고, 무역풍은 저위도(위도 0°~30°)에서 부는 바람이다.'])

