QF(T, 3, '다음은 이 문제에서 쓰는 기후 구분 기준과 도시 가~마의 자료(가상 자료)이다.\n\n'
   '[기준] 열대 기후: 가장 추운 달의 평균 기온이 18 ℃ 이상이고 강수량이 충분함 / 한대 기후: 가장 따뜻한 달의 평균 기온이 10 ℃ 미만 / 건조 기후: 강수량이 매우 적어 증발량이 강수량보다 많음\n\n'
   '· 가: 최한월 12 ℃, 최난월 27 ℃, 연 강수량 1500 mm\n'
   '· 나: 최한월 −25 ℃, 최난월 5 ℃, 연 강수량 300 mm\n'
   '· 다: 최한월 21 ℃, 최난월 28 ℃, 연 강수량 2200 mm\n'
   '· 라: 최한월 15 ℃, 최난월 34 ℃, 연 강수량 60 mm(증발량이 강수량보다 훨씬 많음)\n'
   '· 마: 최한월 −18 ℃, 최난월 17 ℃, 연 강수량 500 mm\n\n'
   '열대 기후와 한대 기후에 해당하는 도시를 순서대로 옳게 짝지은 것은?',
   ['가, 나', '다, 마', '라, 나', '다, 나', '가, 마'], 3,
   ['최한월 평균 기온이 18 ℃ 이상인 도시는 다(21 ℃)뿐이고, 다는 강수량도 많으므로 열대 기후이다. 가(12 ℃)와 라(15 ℃)는 18 ℃에 못 미친다.',
    '최난월 평균 기온이 10 ℃ 미만인 도시는 나(5 ℃)이므로 한대 기후이다. 마는 최난월이 17 ℃로 10 ℃ 이상이어서 한대 기후가 아니다.',
    '라는 증발량이 강수량보다 훨씬 많은 건조 기후이다. 따라서 열대는 다, 한대는 나이다.'])

