Q(T, 4, '북반구의 한 관측소에서 측정한 대기 중 이산화 탄소 농도(ppm)의 월별 값(가상 자료)이다.\n\n'
  '· 첫해: 1월 418.0, 5월 421.0, 9월 415.0, 12월 418.0\n· 다음 해: 1월 420.5, 5월 423.5, 9월 417.5, 12월 420.5\n\n이 자료에 대한 해석으로 옳은 것은?',
  '해마다 5월 무렵 높고 9월 무렵 낮은 것은 북반구 식물의 광합성이 활발한 여름철에 이산화 탄소가 많이 흡수되기 때문이다.',
  ['해마다 9월 무렵 농도가 낮은 것은 이 시기에 화석 연료 사용이 가장 많기 때문이다.',
   '같은 달끼리 비교하면 1년 동안 농도가 2.5 ppm 낮아졌다.',
   '한 해 안의 계절 변동 폭(최고 − 최저)은 1년 동안의 농도 증가량보다 작다.',
   '겨울철에는 식물의 광합성이 가장 활발하여 농도가 가장 낮다.'],
  ['봄부터 여름까지 북반구의 식물이 광합성을 활발히 하여 이산화 탄소를 흡수하므로 늦여름~가을(9월 무렵)에 농도가 가장 낮고, 광합성이 약한 겨울 동안 쌓여 늦봄(5월 무렵)에 가장 높다.',
   '같은 달끼리 비교하면 다음 해가 2.5 ppm 높으므로 농도는 해마다 늘고 있다.',
   '계절 변동 폭은 421.0 − 415.0 = 6.0 ppm으로 1년 동안의 증가량 2.5 ppm보다 크다.'])

C_emit = 100
left = C_emit * (1 - 0.30 - 0.26)
eq(left, 44); eq(left / 20, 2.2); eq(C_emit * 44 / 12, 366.6666666666667)
G(T, 5, '다음은 어느 해의 인위적 탄소 배출과 그 행방을 단순화한 자료(가상 자료)이다.\n\n'
  '· 화석 연료 연소 등으로 배출된 탄소: 100억 t\n· 이 가운데 30 %는 육상 생태계가, 26 %는 해양이 흡수하고 나머지는 대기에 남는다.\n'
  '· 대기 중 탄소 20억 t은 이산화 탄소 농도 1 ppm에 해당한다고 가정한다. (원자량: C 12, O 16)',
  [('대기에 남는 탄소는 44억 t이다.', True,
    '100 × (1 − 0.30 − 0.26) = 100 × 0.44 = 44억 t'),
   ('이 해에 대기 중 이산화 탄소 농도는 약 2.2 ppm 높아진다.', True,
    '44억 t ÷ 20억 t/ppm = 2.2 ppm'),
   ('배출된 탄소 100억 t을 이산화 탄소의 질량으로 바꾸면 약 44억 t이다.', False,
    '이산화 탄소(분자량 44) 속 탄소(12)의 비율로 바꾸면 100 × 44 ÷ 12 ≈ 367억 t이다. 44는 탄소 12 g이 이산화 탄소 44 g이 된다는 비율을 잘못 쓴 값이다')],
  pre=['탄소의 질량과 이산화 탄소의 질량은 12 : 44의 비율이다.'])

