Q(T, 2, '높은 산을 오를 때 나타나는 식생의 변화가 적도에서 극지방으로 갈 때 나타나는 식생의 변화와 비슷한 까닭으로 가장 적절한 것은?',
  '높이 올라갈수록 기온이 낮아지기 때문이다.',
  ['높이 올라갈수록 강수량이 늘어나기 때문이다.',
   '높이 올라갈수록 빛의 세기가 약해지기 때문이다.',
   '높이 올라갈수록 토양이 깊어지기 때문이다.',
   '높이 올라갈수록 기압이 높아지기 때문이다.'],
  ['해발 고도가 높아지면 기온이 낮아진다.',
   '위도가 높아질 때도 기온이 낮아지므로, 두 경우 모두 기온 변화에 따라 식생이 비슷한 순서로 바뀐다(식생의 수평 분포와 수직 분포).',
   '높은 곳일수록 기압은 오히려 낮아진다.'])

cur = {'A': 12, 'B': 10, 'C': 7}
ok = lambda t: 8 <= t <= 11
assert [k for k in cur if ok(cur[k])] == ['B'] and [k for k in cur if ok(cur[k] + 2)] == ['C']
Q(T, 3, '어느 과일 나무는 연평균 기온이 8~11 ℃인 곳에서 재배하기에 알맞다(가상 자료). 세 지역의 현재 연평균 기온은 A 12 ℃, B 10 ℃, C 7 ℃이다. 앞으로 세 지역의 연평균 기온이 똑같이 2 ℃ 오른다면, 이에 대한 설명으로 옳은 것은?',
  '현재 재배에 알맞은 곳은 B이고, 2 ℃ 오른 뒤에는 C가 알맞은 곳이 된다.',
  ['현재 재배에 알맞은 곳은 A이다.',
   '2 ℃ 오른 뒤에도 B는 계속 재배에 알맞다.',
   '2 ℃ 오른 뒤에는 세 지역 모두 재배에 알맞지 않다.',
   '2 ℃ 오른 뒤에는 B와 C 모두 재배에 알맞다.'],
  ['현재 8~11 ℃ 범위에 드는 곳은 B(10 ℃)뿐이다. A(12 ℃)는 너무 따뜻하고 C(7 ℃)는 너무 춥다.',
   '2 ℃ 오르면 A 14 ℃, B 12 ℃, C 9 ℃가 되어 C만 범위에 든다.',
   '이처럼 기온이 오르면 작물의 재배 적지가 더 추운 곳(고위도·고지대)으로 옮겨 간다.'])

Q(T, 3, '기온 상승에 따른 생물 분포의 변화에 대한 설명으로 옳지 않은 것은?',
  '기온이 오르면 고산 식물이 사는 곳의 아래쪽 경계가 산 아래쪽으로 내려온다.',
  ['따뜻한 곳에 사는 식물의 분포 북쪽 한계선이 점점 북쪽으로 올라간다.',
   '찬 바다를 좋아하는 어종은 우리나라 주변 바다에서 잡히는 양이 줄 수 있다.',
   '봄꽃이 피는 시기가 과거보다 빨라진다.',
   '곤충이 활동을 시작하는 시기가 빨라질 수 있다.'],
  ['기온이 오르면 생물은 알맞은 온도를 찾아 고위도·고지대로 분포를 옮긴다.',
   '따라서 고산 식물의 아래쪽 경계는 산 위쪽으로 올라가고, 산꼭대기 근처로 서식지가 좁아진다.',
   '나머지는 기온 상승으로 나타나는 옳은 변화이다.'])

low0, low1, top = 1100, 1300, 1700
dT, lapse = 1.0, 0.5 / 100
assert dT / lapse == low1 - low0 == 200 and (top - low1) / (top - low0) == 400 / 600
Q(T, 4, '어느 산(정상 1700 m)에서 식물 X가 자라는 고도 범위를 조사한 결과(가상 자료)이다.\n\n'
  '· 1980년: 해발 1100 m ~ 정상(1700 m)\n· 2020년: 해발 1300 m ~ 정상(1700 m)\n'
  '· 같은 기간 이 지역의 연평균 기온은 1.0 ℃ 올랐고, 기온은 높이 100 m마다 0.5 ℃씩 낮아진다고 가정한다.\n\n이 자료에 대한 해석으로 옳은 것은?',
  '관측된 아래쪽 경계의 이동 폭(200 m)은 기온 상승 1.0 ℃로 예상되는 이동 폭과 같다.',
  ['기온 상승으로 예상되는 아래쪽 경계의 이동 폭은 50 m이다.',
   'X가 자라는 고도 범위의 폭은 절반으로 줄었다.',
   '기온이 앞으로 1.0 ℃ 더 오르면 X가 자라는 고도 범위의 폭은 300 m가 된다.',
   'X가 자라는 곳의 아래쪽 경계는 40년 동안 산 아래쪽으로 내려왔다.'],
  ['기온이 1.0 ℃ 오르면 같은 기온인 높이가 1.0 ÷ 0.5 × 100 = 200 m 위로 올라간다. 관측된 이동도 1300 − 1100 = 200 m로 같다.',
   '범위의 폭은 600 m → 400 m로 3분의 2가 되었다(절반이 아니다).',
   '1.0 ℃ 더 오르면 아래쪽 경계가 1500 m가 되어 폭은 200 m로 줄어든다. 산꼭대기보다 더 올라갈 곳이 없으므로 서식지가 계속 좁아진다.'])

G(T, 5, '어느 지역에서 벚나무가 꽃을 피운 날짜의 10년 평균값(가상 자료)이다.\n\n'
  '· 1990년대: 4월 10일\n· 2000년대: 4월 6일\n· 2010년대: 4월 2일\n· 같은 기간 이 지역의 2~3월 평균 기온은 꾸준히 올랐다.',
  [('꽃이 피는 날짜는 10년마다 평균 4일씩 빨라졌다.', True, '4월 10일 → 4월 6일 → 4월 2일로 10년마다 4일씩 빨라졌다'),
   ('꽃이 피는 시기에 영향을 주는 주요 비생물적 요인으로 봄철 기온을 들 수 있다.', True,
    '2~3월 기온이 오르는 동안 개화가 빨라졌으므로 봄철 기온이 개화 시기에 영향을 준다고 볼 수 있다'),
   ('꽃가루를 옮기는 곤충의 활동 시기가 그대로라면 식물과 곤충의 활동 시기가 어긋날 수 있다.', True,
    '개화 시기만 빨라지면 꽃이 필 때 곤충이 아직 활동하지 않아 꽃가루받이가 줄 수 있다')])

