Q(T, 4, '다음은 1년 동안 대기로 드나드는 탄소의 양을 단순화한 자료(가상 자료, 단위: 억 t)이다.\n\n'
  '· 육상: 광합성으로 대기에서 흡수 1200, 생물의 호흡과 분해로 대기에 방출 1180\n'
  '· 해양: 대기에서 흡수 800, 대기로 방출 775\n'
  '· 인간 활동: 화석 연료 연소로 방출 95, 삼림 파괴 등 토지 이용 변화로 방출 10\n\n이 해에 대기 중 탄소량의 변화로 옳은 것은?',
  '60억 t 증가', ['105억 t 증가', '50억 t 증가', '85억 t 증가', '60억 t 감소'],
  ['대기로 들어온 양: 1180 + 775 + 95 + 10 = 2060, 대기에서 나간 양: 1200 + 800 = 2000이다.',
   '따라서 대기 중 탄소는 2060 − 2000 = 60억 t 늘었다. 인간 활동 배출 105 중 육상이 20, 해양이 25를 흡수하고 나머지가 대기에 남은 것이다.',
   '105억 t은 자연의 흡수를 무시한 값, 50억 t은 토지 이용 변화의 배출을 빠뜨린 값, 85억 t은 해양의 흡수를 빠뜨린 값이다.'])

