# Ⅱ. 기후위기와 환경생태 변화 — 기후변화의 원인과 양상
# ══════════════════════════════════════════════════════════════
T = 'u1m0s0t0'  # 기후변화 원인 자료 해석
Q(T, 1, '지구의 공전 궤도 모양(이심률), 자전축의 경사각, 자전축의 방향(세차 운동)이 오랜 주기로 바뀌어 기후가 변하는 것은 기후 변화 요인 가운데 어디에 속하는가?',
  '자연적 요인 중 지구 외적 요인(천문학적 요인)',
  ['자연적 요인 중 지구 내적 요인(화산 활동)',
   '자연적 요인 중 지구 내적 요인(수륙 분포의 변화)',
   '인위적 요인(화석 연료 사용)',
   '인위적 요인(토지 이용의 변화)'],
  ['기후 변화 요인은 자연적 요인과 인위적 요인으로 나뉘고, 자연적 요인은 다시 지구 외적 요인과 지구 내적 요인으로 나뉜다.',
   '공전 궤도 이심률, 자전축 경사각, 세차 운동의 변화는 지구의 운동이 바뀌는 것으로 지구 외적 요인(천문학적 요인)이다. 태양 활동의 변화도 지구 외적 요인이다.',
   '화산 활동·수륙 분포 변화·지표 반사율 변화는 지구 내적 요인, 화석 연료 사용·토지 이용 변화는 인위적 요인이다.'])

Q(T, 2, '다른 조건은 변하지 않고 지구 자전축의 경사각만 지금(약 23.5°)보다 커진다면, 북반구 중위도 지역에서 나타날 변화로 옳은 것은?',
  '여름 기온은 높아지고 겨울 기온은 낮아져 기온의 연교차가 커진다.',
  ['여름 기온은 낮아지고 겨울 기온은 높아져 기온의 연교차가 작아진다.',
   '여름과 겨울의 기온이 모두 낮아진다.',
   '계절에 따른 기온 변화가 전혀 나타나지 않는다.',
   '남반구에서만 기온의 연교차가 커지고 북반구는 변화가 없다.'],
  ['자전축 경사각이 커지면 여름철 태양의 남중 고도는 더 높아지고 겨울철 남중 고도는 더 낮아진다.',
   '그래서 여름은 더 덥고 겨울은 더 추워져 기온의 연교차가 커진다.',
   '이 변화는 북반구와 남반구에서 모두 나타난다.'])

Q(T, 3, '현재 지구는 1월 초에 태양과 가장 가까운 근일점을, 7월 초에 가장 먼 원일점을 지난다. 세차 운동으로 약 13000년 뒤 지구 자전축의 기울어진 방향이 지금과 반대가 된다면, 이때의 모습으로 옳은 것은? (단, 세차 운동 외의 다른 조건은 변하지 않는다.)',
  '북반구는 근일점 부근에서 여름이 되어 지금보다 기온의 연교차가 커진다.',
  ['북반구는 근일점 부근에서 겨울이 되어 지금보다 기온의 연교차가 작아진다.',
   '남반구는 지금보다 기온의 연교차가 커진다.',
   '세차 운동의 주기는 약 10만 년이므로 13000년 뒤에는 아무 변화가 없다.',
   '현재 북반구는 원일점 부근에서 겨울을 맞는다.'],
  ['지금 북반구는 근일점(1월) 부근에서 겨울, 원일점(7월) 부근에서 여름을 맞아 계절에 따른 기온 차가 조금 줄어든다.',
   '자전축 방향이 반대가 되면 북반구는 근일점 부근에서 여름(더 더움), 원일점 부근에서 겨울(더 추움)을 맞아 연교차가 커진다. 반대로 남반구는 연교차가 작아진다.',
   '세차 운동의 주기는 약 26000년이며, 약 10만 년은 공전 궤도 이심률이 변하는 주기이다.'])

Q(T, 3, '기후 변화의 자연적 요인에 대한 설명으로 옳지 않은 것은?',
  '대규모 화산 폭발로 성층권에 퍼진 미세한 입자(에어로졸)는 지표에 도달하는 햇빛을 늘려 몇 년 동안 지구 기온을 높인다.',
  ['태양 활동은 약 11년을 주기로 활발해졌다 약해졌다를 되풀이한다.',
   '판의 운동으로 대륙의 위치와 수륙 분포가 바뀌면 해류와 기후가 달라진다.',
   '지표의 반사율 변화도 지구가 흡수하는 에너지의 양을 바꾸어 기후에 영향을 준다.',
   '공전 궤도 이심률, 자전축 경사각, 세차 운동은 수만~수십만 년 주기로 기후에 영향을 준다.'],
  ['대규모 화산 폭발로 성층권에 퍼진 에어로졸은 햇빛을 반사·산란하여 지표에 도달하는 태양 복사 에너지를 줄인다.',
   '그래서 폭발 뒤 1~2년 정도 지구의 평균 기온이 일시적으로 낮아진다.',
   '나머지 설명은 모두 옳다.'])

co2 = {1960: 317, 1980: 339, 2000: 370, 2020: 414}
tsi = {1960: 0.1, 1980: 0.1, 2000: 0.0, 2020: -0.1}
tan = {1960: 0.0, 1980: 0.2, 2000: 0.4, 2020: 0.9}
assert co2[2020] / co2[1960] < 2 and tsi[2020] < tsi[1960] and tan[2020] > tan[1960]
Q(T, 4, '다음은 몇 해의 태양 복사 세기 변화, 대기 중 이산화 탄소 농도, 지구 평균 기온 편차를 단순화하여 나타낸 자료(가상 자료)이다.\n\n'
  '· 연도: 1960, 1980, 2000, 2020\n· 태양 복사 세기의 편차(W/m²): +0.1, +0.1, 0.0, −0.1\n'
  '· 이산화 탄소 농도(ppm): 317, 339, 370, 414\n· 지구 평균 기온 편차(℃): 0.0, +0.2, +0.4, +0.9\n\n이 자료에 대한 해석으로 가장 적절한 것은?',
  '이 기간의 기온 상승은 태양 복사의 변화보다 이산화 탄소 농도의 증가와 더 밀접하게 나타난다.',
  ['이 기간에 태양 복사가 꾸준히 강해져 기온이 올랐다.',
   '이 기간에 이산화 탄소 농도는 줄어들었다.',
   '기온 편차와 태양 복사 세기의 편차는 같은 방향으로 변하였다.',
   '이산화 탄소 농도는 60년 동안 2배 이상이 되었다.'],
  ['태양 복사 세기의 편차는 약간 줄어드는 방향(+0.1 → −0.1)인데 기온은 계속 올랐으므로, 태양 활동으로는 기온 상승을 설명하기 어렵다.',
   '이산화 탄소 농도는 317 → 414 ppm으로 늘었고 기온도 함께 올라 두 값이 같은 방향으로 변하였다.',
   '414 ÷ 317 ≈ 1.3이므로 2배가 되지는 않았다.'])

G(T, 5, '지구 공전 궤도와 자전축의 변화에 대하여 학생이 다음과 같이 정리하였다.',
  [('지구 공전 궤도의 이심률이 변하는 주기는 약 10만 년이다.', True,
    '공전 궤도 이심률은 약 10만 년을 주기로 변한다'),
   ('자전축 경사각이 지금보다 작아지면 북반구와 남반구 모두 기온의 연교차가 커진다.', False,
    '경사각이 작아지면 여름과 겨울의 태양 남중 고도 차이가 줄어 두 반구 모두 연교차가 작아진다'),
   ('공전 궤도가 완전한 원(이심률 0)이 되면 근일점과 원일점에서 받는 태양 복사 에너지의 차이가 지금보다 커진다.', False,
    '원 궤도에서는 태양까지의 거리가 늘 같아 근일점과 원일점의 구분이 없어지므로 그 차이도 없어진다')])

