Q(T, 2, '공장과 자동차에서 배출된 황산염 같은 에어로졸이 대기 중에 늘어날 때 지표의 기온에 주는 영향으로 가장 적절한 것은?',
  '햇빛을 반사하거나 산란시켜 지표에 도달하는 태양 복사 에너지를 줄이므로 기온을 낮추는 방향으로 작용한다.',
  ['지구 복사를 모두 흡수하여 기온을 크게 높인다.',
   '오존층을 두껍게 만들어 기온을 높인다.',
   '대기 중 이산화 탄소를 흡수하여 온실 효과를 없앤다.',
   '기온에는 아무런 영향을 주지 않는다.'],
  ['황산염 같은 에어로졸은 햇빛을 반사·산란하고 구름의 반사율에도 영향을 준다.',
   '그래서 지표에 도달하는 태양 복사 에너지를 줄여 기온을 낮추는 방향으로 작용한다(냉각 효과).',
   '즉 인위적 요인 가운데에는 온실 기체처럼 기온을 높이는 것도, 에어로졸처럼 낮추는 것도 있다.'])

Q(T, 3, '다음 (가)~(라) 가운데 기후 변화의 인위적 요인만을 있는 대로 고른 것은?\n\n'
  '(가) 태양 활동이 약해져 흑점 수가 줄었다.\n(나) 도시가 넓어지면서 숲과 논이 아스팔트와 건물로 바뀌었다.\n'
  '(다) 대규모 화산 폭발로 많은 화산재가 뿜어져 나왔다.\n(라) 가축 사육이 크게 늘어 메테인 배출이 많아졌다.',
  '(나), (라)', ['(가), (다)', '(가), (나)', '(다), (라)', '(나), (다), (라)'],
  ['(나) 도시화에 따른 토지 이용 변화는 사람의 활동으로 지표의 성질(반사율·열 저장·증발량)을 바꾸므로 인위적 요인이다.',
   '(라) 가축 사육으로 늘어난 메테인은 사람의 활동으로 늘어난 온실 기체이므로 인위적 요인이다.',
   '(가) 태양 활동과 (다) 화산 폭발은 자연적 요인이다.'])

Q(T, 3, '기후 변화 요인이 영향을 주는 시간 규모에 대한 설명으로 옳지 않은 것은?',
  '공전 궤도 이심률, 자전축 경사각, 세차 운동의 변화에 따른 기후 변화는 수십 년 안에 뚜렷하게 나타난다.',
  ['판의 운동에 따른 수륙 분포의 변화는 수백만 년 이상의 긴 시간에 걸쳐 기후에 영향을 준다.',
   '대규모 화산 폭발에 따른 냉각 효과는 보통 수년 안에 사라진다.',
   '산업 혁명 이후 온실 기체 농도는 약 200년 사이에 빠르게 늘었다.',
   '태양 활동은 약 11년 주기로 변한다.'],
  ['공전 궤도 이심률(약 10만 년), 자전축 경사각(약 4만 1천 년), 세차 운동(약 26000년)은 수만~수십만 년 주기로 기후에 영향을 준다.',
   '따라서 수십 년 안에 뚜렷한 변화를 일으키지 않는다. 최근 수십 년의 빠른 온난화를 이 요인으로 설명하기 어려운 까닭이다.',
   '나머지 설명은 모두 옳다.'])

