Q(T, 4, '기후 모형으로 1950~2020년의 지구 평균 기온 변화를 계산한 결과(가상 자료)이다.\n\n'
  '· 실제 관측값: +1.0 ℃\n· 자연적 요인만 넣은 계산: 0.0 ℃\n· 인위적 온실 기체만 넣은 계산: +1.3 ℃\n'
  '· 인위적 에어로졸만 넣은 계산: −0.3 ℃\n· 자연적 요인과 인위적 요인을 모두 넣은 계산: +1.0 ℃\n\n이 자료에 대한 해석으로 옳은 것은?',
  '관측된 기온 상승은 인위적 요인을 넣어야 재현되며, 에어로졸은 온실 기체에 의한 기온 상승의 일부를 상쇄하였다.',
  ['자연적 요인만으로도 관측된 기온 상승을 재현할 수 있다.',
   '에어로졸은 기온을 0.3 ℃ 더 높이는 효과를 냈다.',
   '온실 기체만의 효과는 관측된 기온 상승보다 작다.',
   '자연적 요인은 이 기간에 기온을 0.3 ℃ 낮추었다.'],
  ['자연적 요인만 넣으면 0.0 ℃로 관측값(+1.0 ℃)을 재현하지 못하고, 인위적 요인까지 넣어야 +1.0 ℃가 재현된다.',
   '온실 기체만의 효과(+1.3 ℃)는 관측값보다 크고, 에어로졸(−0.3 ℃)이 그 일부를 상쇄하였다.',
   '기온을 0.3 ℃ 낮춘 것은 자연적 요인이 아니라 인위적 에어로졸이다.'])

G(T, 5, '기후 변화의 자연적 요인과 인위적 요인을 비교하여 학생이 다음과 같이 정리하였다.',
  [('자연적 요인에 의한 기후 변화는 인류가 나타나기 이전에도 일어났다.', True,
    '빙하기와 간빙기의 반복처럼 자연적 요인에 의한 기후 변화는 지구 역사 내내 있었다'),
   ('인위적 요인 가운데에는 지구 기온을 낮추는 방향으로 작용하는 것도 있다.', True,
    '사람이 배출한 황산염 에어로졸은 햇빛을 반사하여 냉각 효과를 낸다'),
   ('산업 혁명 이후 대기 중 이산화 탄소 농도가 빠르게 늘어난 것은 주로 화석 연료 사용과 삼림 파괴 때문이다.', True,
    '화석 연료 연소와 삼림 파괴 같은 토지 이용 변화가 이산화 탄소 증가의 주된 원인이다')])

T = 'u1m0s0t2'  # 온실가스 배출 자료 분석
Q(T, 1, '전 세계에서 사람의 활동으로 배출되는 온실 기체를 이산화 탄소 환산량으로 비교할 때 가장 큰 비중을 차지하는 기체는?',
  '이산화 탄소(CO₂)', ['메테인(CH₄)', '아산화 질소(N₂O)', '수소불화탄소(HFCs)', '육불화 황(SF₆)'],
  ['사람의 활동으로 배출되는 온실 기체 가운데 이산화 탄소가 이산화 탄소 환산량 기준으로 가장 큰 비중을 차지한다.',
   '이산화 탄소는 주로 화석 연료의 연소와 삼림 파괴로 배출된다.',
   '메테인·아산화 질소·수소불화탄소·육불화 황은 같은 질량당 온실 효과는 크지만 배출량이 훨씬 적다.'])

