Q(T, 3, '온실 기체 배출 지표에 대한 설명으로 옳지 않은 것은?',
  '총배출량이 많은 나라는 1인당 배출량도 반드시 많다.',
  ['1인당 배출량은 총배출량을 인구로 나눈 값이다.',
   '누적 배출량은 과거부터 배출한 양을 모두 더한 값이다.',
   'GDP당 배출량이 줄어도 경제 규모가 커지면 총배출량은 늘 수 있다.',
   '같은 나라라도 어떤 지표를 쓰느냐에 따라 배출 책임에 대한 평가가 달라질 수 있다.'],
  ['총배출량이 많아도 인구가 매우 많으면 1인당 배출량은 적을 수 있다.',
   '반대로 인구가 적은 나라는 총배출량이 적어도 1인당 배출량이 많을 수 있다.',
   '그래서 총배출량·1인당 배출량·누적 배출량·GDP당 배출량을 함께 보아야 한다.'])

A = dict(e=10e8, p=2e8, g=5e12); B = dict(e=4e8, p=2e7, g=1e12)
pcA, pcB = A['e'] / A['p'], B['e'] / B['p']
inA, inB = A['e'] / A['g'] * 1e6, B['e'] / B['g'] * 1e6
assert (pcA, pcB) == (5, 20) and round(inA) == 200 and round(inB) == 400
Q(T, 4, '두 나라 A, B의 자료(가상 자료)이다.\n\n'
  '· A: 연간 배출량 10억 t, 인구 2억 명, GDP 5조 달러\n· B: 연간 배출량 4억 t, 인구 2000만 명, GDP 1조 달러\n\n이에 대한 설명으로 옳은 것은?',
  '1인당 배출량과 GDP 1달러당 배출량 모두 B가 A보다 많다.',
  ['1인당 배출량은 A가 B보다 많다.',
   '총배출량은 B가 A보다 많다.',
   'B의 1인당 배출량은 A의 2배이다.',
   'GDP 1달러당 배출량은 A가 B의 2배이다.'],
  ['1인당 배출량: A는 10억 ÷ 2억 = 5 t, B는 4억 ÷ 2000만 = 20 t으로 B가 A의 4배이다.',
   'GDP 100만 달러당 배출량: A는 10억 t ÷ 5조 달러 × 100만 = 200 t, B는 4억 t ÷ 1조 달러 × 100만 = 400 t으로 B가 A의 2배이다.',
   '총배출량은 A(10억 t)가 B(4억 t)보다 많다. 총배출량과 1인당·GDP당 배출량은 서로 다른 모습을 보일 수 있다.'])

