Q(T, 3, '빙하 코어 속 얼음의 산소 동위 원소비(¹⁸O/¹⁶O)로 과거의 기온을 추정할 수 있다. 같은 곳의 빙하 코어에서 A층 얼음의 ¹⁸O/¹⁶O가 B층보다 높게 나타났다면, 이에 대한 해석으로 옳은 것은?',
  'A층이 쌓일 때가 B층이 쌓일 때보다 기온이 높았다.',
  ['A층이 쌓일 때가 B층이 쌓일 때보다 기온이 낮았다.',
   '두 층이 쌓일 때의 기온은 같았다.',
   'A층이 쌓일 때 빙하의 면적이 가장 넓었다.',
   '산소 동위 원소비는 기온과 관계가 없다.'],
  ['무거운 ¹⁸O가 든 물 분자는 증발하기 어렵고 응결하기 쉬워, 기온이 낮을수록 극지방까지 가기 전에 비나 눈으로 먼저 빠져나간다.',
   '그래서 기온이 낮은 시기에 극지방에 쌓인 눈(빙하)은 ¹⁸O/¹⁶O가 낮고, 기온이 높은 시기에는 높다.',
   '따라서 ¹⁸O/¹⁶O가 높은 A층이 쌓일 때가 더 따뜻했다.'])

Q(T, 3, '과거 기후를 알려 주는 자료에 대한 설명으로 옳지 않은 것은?',
  '빙하기에는 간빙기보다 해수의 ¹⁸O/¹⁶O가 낮았다.',
  ['빙하기에는 빙하가 넓어져 해수면이 간빙기보다 낮았다.',
   '해양 생물 껍데기의 ¹⁸O/¹⁶O가 높은 층은 빙하기에 쌓였을 가능성이 크다.',
   '꽃가루 화석을 분석하면 당시의 식생과 기후를 추정할 수 있다.',
   '빙하 코어의 공기 방울로 과거 대기의 이산화 탄소 농도를 알 수 있다.'],
  ['빙하기에는 가벼운 ¹⁶O가 든 물이 증발해 눈이 되어 빙하에 많이 갇히므로, 바다에는 무거운 ¹⁸O가 상대적으로 많이 남는다.',
   '그래서 빙하기의 해수는 ¹⁸O/¹⁶O가 높고, 그 해수로 껍데기를 만든 해양 생물의 ¹⁸O/¹⁶O도 높다.',
   '빙하기에 해수의 ¹⁸O/¹⁶O가 낮았다는 진술은 거꾸로 되었다.'])

core = {'P': (280, 1.00), 'Q': (190, 0.95), 'R': (270, 0.99)}
order_c = sorted(core, key=lambda k: core[k][0]); order_t = sorted(core, key=lambda k: core[k][1])
assert order_c == order_t == ['Q', 'R', 'P'] and core['Q'][0] > core['P'][0] / 2
Q(T, 4, '남극 빙하 코어에서 세 시기 P, Q, R의 자료를 얻었다(가상 자료). 빙하 속 얼음의 ¹⁸O/¹⁶O는 기온이 높은 시기일수록 크다.\n\n'
  '· P: 이산화 탄소 280 ppm, 얼음의 ¹⁸O/¹⁶O 상댓값 1.00\n· Q: 이산화 탄소 190 ppm, 얼음의 ¹⁸O/¹⁶O 상댓값 0.95\n'
  '· R: 이산화 탄소 270 ppm, 얼음의 ¹⁸O/¹⁶O 상댓값 0.99\n\n이 자료에 대한 해석으로 옳은 것은?',
  'Q 시기가 세 시기 가운데 가장 추웠을 가능성이 크고, 이산화 탄소 농도가 높은 시기일수록 기온도 높은 경향을 보인다.',
  ['Q 시기가 세 시기 가운데 가장 따뜻했다.',
   '이산화 탄소 농도가 높은 시기일수록 기온이 낮은 경향을 보인다.',
   'P 시기에는 R 시기보다 기온이 낮았다.',
   'Q 시기의 이산화 탄소 농도는 P 시기의 절반보다 낮다.'],
  ['얼음의 ¹⁸O/¹⁶O가 가장 작은 Q가 가장 추웠고, 가장 큰 P가 가장 따뜻했다(Q < R < P).',
   '이산화 탄소 농도도 Q(190) < R(270) < P(280)의 순서여서 기온과 같은 방향으로 변하였다.',
   'Q의 농도 190 ppm은 P의 절반(140 ppm)보다 높다.'])

G(T, 5, '기후 변화의 증거에 대하여 학생들이 다음과 같이 정리하였다.',
  [('전 세계 산악 빙하의 대부분이 줄어들고 있는 것은 지구 온난화를 뒷받침하는 증거이다.', True,
    '기온이 오르면 빙하가 녹는 양이 쌓이는 양보다 많아져 빙하가 줄어든다'),
   ('해양 퇴적물 속 유공충 껍데기의 ¹⁸O/¹⁶O가 높은 층은 기온이 높았던 시기에 쌓였다.', False,
    '해양 생물 껍데기의 ¹⁸O/¹⁶O가 높은 것은 해수의 ¹⁸O/¹⁶O가 높았던 빙하기(추운 시기)를 뜻한다'),
   ('꽃가루 화석에서 추운 기후에 사는 식물의 꽃가루 비율이 높은 층은 기온이 낮았던 시기에 쌓였을 것이다.', True,
    '꽃가루 화석으로 당시 번성한 식물을 알면 당시의 기후를 추정할 수 있다')],
  pre=['빙하 얼음의 ¹⁸O/¹⁶O와 해양 생물 껍데기의 ¹⁸O/¹⁶O는 기온에 대해 반대로 움직인다는 점에 주의한다.'])

T = 'u1m0s1t0'  # 지구온난화 지표 자료 해석
Q(T, 1, '다음 중 지구 온난화가 진행될 때 나타나는 변화로 옳은 것은?',
  '북극 바다의 해빙 면적이 줄어든다.',
  ['산악 빙하가 넓어진다.', '해수면이 낮아진다.', '해양에 저장된 열에너지가 줄어든다.', '영구 동토층의 면적이 넓어진다.'],
  ['지구 온난화가 진행되면 해빙과 빙하가 녹아 줄어든다.',
   '해수의 열팽창과 육지 빙하의 융해로 해수면은 높아지고, 해양이 흡수해 저장한 열에너지도 늘어난다.',
   '영구 동토층은 녹으면서 면적이 줄어든다.'])

eq(14.0 + 0.8, 14.8)
Q(T, 2, '어느 해의 지구 평균 기온 편차가 +0.8 ℃였다. 기온 편차는 그해의 평균 기온에서 기준 기간의 평균 기온을 뺀 값이다. 기준 기간의 평균 기온이 14.0 ℃라고 할 때(계산을 위한 값), 그해의 지구 평균 기온은?',
  '14.8 ℃', ['13.2 ℃', '0.8 ℃', '14.08 ℃', '15.8 ℃'],
  ['기온 편차 = 그해의 평균 기온 − 기준 기간의 평균 기온이다.',
   '그해의 평균 기온 = 14.0 + 0.8 = 14.8 ℃이다.',
   '13.2 ℃는 편차를 빼 준 값이고, 0.8 ℃는 편차 자체를 답으로 쓴 값이다.'])

ice = {1980: 7.5, 2000: 6.3, 2020: 3.9}
d1_, d2_ = ice[1980] - ice[2000], ice[2000] - ice[2020]
eq(d1_, 1.2); eq(d2_, 2.4); eq(d2_ / d1_, 2)
assert 0.5 < ice[2020] / ice[1980] < 0.53
Q(T, 3, '해마다 북극 해빙의 면적이 가장 작아지는 9월의 해빙 면적(가상 자료, 단위: 백만 km²)이다.\n\n'
  '· 1980년 7.5, 2000년 6.3, 2020년 3.9\n\n이 자료에 대한 해석으로 옳은 것은?',
  '2000~2020년의 감소량은 1980~2000년 감소량의 2배이다.',
  ['1980년에 비해 2020년에는 해빙 면적이 절반 넘게 줄었다.',
   '해빙 면적의 감소 속도가 점점 느려지고 있다.',
   '2020년의 해빙 면적은 1980년의 약 48 %이다.',
   '북극 해빙이 녹는 것은 해수면 상승의 주된 원인이다.'],
  ['감소량은 1980~2000년 7.5 − 6.3 = 1.2, 2000~2020년 6.3 − 3.9 = 2.4로 뒤 기간이 2배이다. 감소 속도가 빨라지고 있다.',
   '2020년 면적은 1980년의 3.9 ÷ 7.5 = 52 %로, 줄어든 비율은 48 %이다. 절반 넘게 줄지는 않았다.',
   '해빙은 이미 바다에 떠 있는 얼음이어서 녹아도 해수면을 거의 높이지 않는다.'])

Q(T, 3, '지구 온난화의 양상에 대한 설명으로 옳지 않은 것은?',
  '지구 온난화가 진행되면 모든 지역의 기온이 같은 폭으로 오른다.',
  ['북극 지방은 지구 평균보다 기온이 빠르게 오르고 있다.',
   '대체로 육지는 바다보다 기온이 빠르게 오른다.',
   '해양은 온난화로 늘어난 열에너지의 대부분을 흡수하여 저장한다.',
   '세계 곳곳의 산악 빙하가 줄어들고 있다.'],
  ['지구 온난화는 지구 평균 기온이 오르는 것이며, 지역마다 오르는 폭이 다르다.',
   '북극은 얼음이 녹아 반사율이 줄어드는 되먹임 등으로 지구 평균보다 빠르게 데워지고, 비열이 작은 육지는 바다보다 빨리 데워진다.',
   '나머지 설명은 모두 옳다.'])

an = {1990: 0.4, 2000: 0.5, 2010: 0.75, 2020: 1.0}
rate = (an[2020] - an[2010]) / 10
eq(2020 + (1.5 - an[2020]) / rate, 2040); eq(an[2020] / an[1990], 2.5)
Q(T, 4, '산업화 이전을 기준으로 한 지구 평균 기온 편차(가상 자료)이다.\n\n'
  '· 1990년 +0.4 ℃, 2000년 +0.5 ℃, 2010년 +0.75 ℃, 2020년 +1.0 ℃\n\n이 자료에 대한 해석으로 옳은 것은?',
  '2010~2020년의 상승 속도가 그대로 유지되면 2040년에 +1.5 ℃에 이른다.',
  ['2010~2020년의 상승 속도가 그대로 유지되면 2030년에 +1.5 ℃에 이른다.',
   '10년당 상승 폭은 점점 작아지고 있다.',
   '10년당 상승 폭은 1990~2000년이 가장 크다.',
   '1990~2020년 동안 기온 편차는 2배가 되었다.'],
  ['2010~2020년에 0.25 ℃ 올랐으므로 10년에 0.25 ℃씩 오르는 속도이다.',
   '+1.0 ℃에서 +1.5 ℃까지 0.5 ℃가 더 오르려면 20년이 걸리므로 2040년에 이른다.',
   '10년당 상승 폭은 0.1 → 0.25 → 0.25 ℃로 커졌고, 1990년 대비 2020년 편차는 1.0 ÷ 0.4 = 2.5배이다.'])

G(T, 5, '지구 온난화의 지표 자료를 해석하는 방법에 대하여 학생들이 다음과 같이 의견을 나누었다.',
  [('한 해의 기온 편차가 전년보다 낮아졌다면 장기적인 온난화 추세가 멈춘 것이다.', False,
    '기온은 해마다 오르내리므로 장기 추세는 수십 년의 자료로 판단해야 한다'),
   ('해수면 상승, 해양 열용량 증가, 빙하 감소가 함께 나타나는 것은 온난화를 여러 방향에서 뒷받침한다.', True,
    '서로 다른 방법으로 측정한 여러 지표가 같은 방향을 가리키므로 온난화의 증거가 된다'),
   ('북극 지방의 기온 상승 속도는 지구 평균보다 빠르다.', True,
    '북극은 해빙이 녹아 반사율이 줄어드는 되먹임 등으로 지구 평균보다 빠르게 데워진다')])

T = 'u1m0s1t1'  # 해수면 상승 영향 분석
Q(T, 1, '지구 온난화에 따른 해수면 상승의 주된 원인 두 가지를 옳게 짝지은 것은?',
  '해수의 열팽창, 육지를 덮은 빙하(빙상)의 융해',
  ['바다에 떠 있는 해빙의 융해, 강수량의 증가',
   '해저 화산 활동의 증가, 해빙의 융해',
   '해수 증발량의 증가, 대기 중 수증기의 증가',
   '조석 간만의 차 증가, 해류의 강화'],
  ['바닷물은 온도가 오르면 부피가 늘어난다(열팽창).',
   '그린란드·남극의 빙상과 산악 빙하처럼 육지에 있던 얼음이 녹아 바다로 흘러들면 바닷물의 양이 늘어난다.',
   '바다에 떠 있는 해빙은 이미 물에 잠긴 만큼 물을 밀어내고 있어 녹아도 해수면을 거의 높이지 않는다.'])

Q(T, 2, '북극 바다에 떠 있는 해빙이 녹을 때 해수면의 변화에 대한 설명으로 가장 적절한 것은?',
  '해빙은 이미 바다에 떠 있으므로 녹아도 해수면을 거의 높이지 않는다.',
  ['해빙이 녹으면 해수면이 크게 높아진다.',
   '해빙이 녹으면 해수면이 크게 낮아진다.',
   '해빙이 녹는 것은 남극 대륙의 빙상이 녹는 것과 해수면에 같은 영향을 준다.',
   '해빙이 녹는 것은 그린란드 빙상이 녹는 것보다 해수면을 더 많이 높인다.'],
  ['물에 떠 있는 얼음은 자기 무게만큼의 물을 밀어내고 있다.',
   '해빙이 녹아 생긴 물은 원래 밀어내던 물의 부피와 거의 같으므로 해수면은 거의 변하지 않는다.',
   '반면 남극·그린란드처럼 육지 위의 빙상이 녹아 흘러들면 바닷물이 늘어 해수면이 높아진다. 다만 해빙이 줄면 반사율이 줄어 온난화를 강화하는 문제는 있다.'])

Q(T, 3, '해수면 상승이 미치는 영향에 대한 설명으로 옳지 않은 것은?',
  '해수면이 높아지면 해안 지역 지하수의 염분이 낮아진다.',
  ['해안의 낮은 땅이 물에 잠길 수 있다.',
   '해안 침식이 심해질 수 있다.',
   '폭풍 해일이 일어났을 때 피해가 커질 수 있다.',
   '해발 고도가 낮은 섬나라는 삶의 터전을 잃을 위험이 커진다.'],
  ['해수면이 높아지면 바닷물이 해안의 땅속으로 더 깊이 스며들어 지하수에 섞인다.',
   '그래서 지하수의 염분이 높아져 마실 물과 농업용수가 부족해질 수 있다.',
   '나머지는 해수면 상승으로 나타나는 옳은 영향이다.'])

rate_sl = (90 - 0) / (2020 - 1990)
eq(rate_sl, 3); eq(rate_sl * (2050 - 1990), 180)
Q(T, 3, '어느 해안 관측소의 해수면 높이는 1990년을 기준(0 mm)으로 할 때 2020년에 +90 mm였다(가상 자료). 해수면이 1990~2020년과 같은 속도로 계속 오른다면, 2050년의 해수면 높이는 1990년보다 몇 mm 높겠는가?',
  '180 mm', ['90 mm', '120 mm', '150 mm', '270 mm'],
  ['1990~2020년 30년 동안 90 mm 올랐으므로 1년에 3 mm씩 올랐다.',
   '1990년부터 2050년까지 60년 동안 오르는 높이는 60 × 3 = 180 mm이다.',
   '90 mm는 2020년의 값, 120 mm와 150 mm는 각각 2030년과 2040년의 값, 270 mm는 2020년의 90 mm에 60년 동안의 상승량 180 mm를 또 더한 값이다.'])

con = {'열팽창': 1.3, '산악 빙하': 0.7, '그린란드 빙상': 0.6, '남극 빙상': 0.4, '기타': 0.2}
eq(sum(con.values()), 3.2)
assert con['산악 빙하'] + con['그린란드 빙상'] + con['남극 빙상'] > con['열팽창'] and con['열팽창'] / 3.2 < 0.5
eq(con['그린란드 빙상'] / con['남극 빙상'], 1.5)
Q(T, 4, '최근 수십 년 동안 지구 평균 해수면이 1년에 3.2 mm씩 오른 원인을 나누어 나타낸 자료(가상 자료, 단위: mm/년)이다.\n\n'
  '· 해수의 열팽창 1.3, 산악 빙하 융해 0.7, 그린란드 빙상 융해 0.6, 남극 빙상 융해 0.4, 기타 0.2\n\n이 자료에 대한 해석으로 옳은 것은?',
  '빙하와 빙상의 융해에 따른 기여를 모두 합하면 열팽창에 따른 기여보다 크다.',
  ['열팽창의 기여가 전체의 절반을 넘는다.',
   '그린란드 빙상 융해의 기여는 남극 빙상 융해의 2배이다.',
   '이 속도가 100년 동안 이어지면 해수면은 약 3.2 m 높아진다.',
   '바다에 떠 있는 해빙의 융해가 가장 큰 원인이다.'],
  ['빙하·빙상 융해의 기여는 0.7 + 0.6 + 0.4 = 1.7 mm/년으로 열팽창(1.3 mm/년)보다 크다.',
   '열팽창은 1.3 ÷ 3.2 ≈ 41 %로 절반이 안 되고, 그린란드(0.6)는 남극(0.4)의 1.5배이다.',
   '100년 동안 3.2 mm × 100 = 320 mm = 약 0.32 m 높아진다. 해빙 융해는 자료에 없고 해수면 상승에 거의 기여하지 않는다.'])

eq(4 * 50, 200)
