Q(T, 3, '어느 도시에서 7일 동안 관측한 기온(가상 자료)이다. 이 문제에서는 일 최고 기온이 33 ℃ 이상인 날을 폭염일, 밤의 최저 기온이 25 ℃ 이상인 날을 열대야로 한다.\n\n'
  '· 일 최고 기온(℃): 31, 33, 35, 32, 34, 36, 30\n· 밤의 최저 기온(℃): 24, 25, 26, 23, 25, 27, 22\n\n폭염일과 열대야의 일수를 옳게 짝지은 것은?',
  '폭염일 4일, 열대야 4일',
  ['폭염일 3일, 열대야 4일', '폭염일 4일, 열대야 2일', '폭염일 3일, 열대야 2일', '폭염일 5일, 열대야 5일'],
  ['「이상」은 그 값을 포함한다.',
   '최고 기온이 33 ℃ 이상인 날은 33, 35, 34, 36 ℃의 4일이고, 최저 기온이 25 ℃ 이상인 날은 25, 26, 25, 27 ℃의 4일이다.',
   '3일이나 2일은 33 ℃·25 ℃인 날을 빼고 「초과」로 센 값이다.'])

