Q(T, 4, '어느 지역의 10년 단위 여름철 강수 자료(가상 자료)이다.\n\n'
  '· 1시간에 50 mm 이상 내린 강한 비의 발생 횟수: 1980년대 10회, 1990년대 14회, 2000년대 18회, 2010년대 25회\n'
  '· 여름철 평균 총강수량: 1980년대 700 mm, 1990년대 720 mm, 2000년대 710 mm, 2010년대 730 mm\n\n이 자료에 대한 해석으로 옳은 것은?',
  '여름철 총강수량의 변화는 작지만 강한 비의 발생 횟수는 크게 늘어, 비가 짧은 시간에 몰려 내리는 경향이 커졌다.',
  ['2010년대 강한 비의 발생 횟수는 1980년대의 3배이다.',
   '여름철 총강수량이 1980년대보다 30 % 이상 늘었다.',
   '강한 비의 발생 횟수는 10년마다 같은 폭으로 늘었다.',
   '강한 비가 줄어 가뭄 위험만 커졌다.'],
  ['총강수량은 700 → 730 mm로 약 4 % 늘었을 뿐이지만, 강한 비의 발생 횟수는 10 → 25회로 2.5배가 되었다.',
   '비의 총량은 비슷한데 강한 비가 잦아졌으므로 비가 짧은 시간에 몰려 내리는 경향이 커졌다고 해석할 수 있다.',
   '횟수 증가 폭은 4, 4, 7회로 일정하지 않다.'])

