T = 'u1m1s0t0'  # 기후변화와 생물다양성 감소 사례 분석
Q(T, 1, '도로나 택지 개발로 하나로 이어져 있던 숲이 여러 조각으로 나뉘어 동물이 이동하기 어려워지는 현상을 무엇이라고 하는가?',
  '서식지 단편화', ['생물 농축', '남획', '외래종 유입', '부영양화'],
  ['하나로 이어진 서식지가 도로·건물 등으로 잘게 나뉘는 것을 서식지 단편화라고 한다.',
   '서식지가 조각나면 각 조각의 면적이 줄고 생물이 이동하기 어려워 개체군이 작아지고 고립된다.',
   '생물 농축은 물질이 먹이 사슬을 따라 쌓이는 현상, 남획은 지나친 사냥·채집, 부영양화는 물에 영양염이 지나치게 많아지는 현상이다.'])

Q(T, 2, '기후 변화가 생물다양성을 감소시키는 과정으로 가장 적절한 것은?',
  '기온이 올라 고산 식물이 살 수 있는 산꼭대기 부근의 서식지가 좁아지면서 개체 수가 줄어든다.',
  ['야생 동물을 지나치게 사냥하여 개체 수가 줄어든다.',
   '공장 폐수가 강으로 흘러들어 물고기가 죽는다.',
   '관상용으로 들여온 외래 식물이 퍼져 토종 식물을 몰아낸다.',
   '숲을 베어 내고 농경지를 만들어 서식지가 사라진다.'],
  ['기온이 오르면 고산 식물은 더 서늘한 위쪽으로 옮겨 가야 하지만 산꼭대기보다 더 올라갈 곳이 없어 서식지가 줄어든다.',
   '이는 기후 변화가 직접 생물다양성을 줄이는 과정이다.',
   '남획, 환경 오염, 외래종 유입, 서식지 파괴도 생물다양성 감소의 원인이지만 기후 변화에 따른 과정은 아니다.'])

Q(T, 3, '우리나라에 들어온 외래 생물과 생물다양성에 대한 설명으로 옳지 않은 것은?',
  '황소개구리는 우리나라 토종 양서류로, 개체 수가 늘수록 생태계가 안정된다.',
  ['뉴트리아는 남아메리카가 원산지인 동물이다.',
   '큰입배스는 북아메리카가 원산지인 물고기로, 토종 물고기를 잡아먹는다.',
   '천적이 없는 환경에 들어온 외래종은 빠르게 번식하여 토종 생물을 위협할 수 있다.',
   '기후가 따뜻해지면 따뜻한 지역에서 온 외래종이 자리 잡기 쉬워질 수 있다.'],
  ['황소개구리는 북아메리카가 원산지인 외래종으로, 토종 개구리·물고기·뱀 등을 잡아먹어 생태계를 교란한다.',
   '외래종은 천적이 없으면 빠르게 불어나 토종 생물과 경쟁하거나 토종 생물을 잡아먹는다.',
   '나머지 설명은 모두 옳다.'])

dd = {'물': 0.00005, '플랑크톤': 0.04, '작은 물고기': 0.5, '큰 물고기': 2.0, '물새': 25.0}
