Q(T, 3, '어느 호수에서 분해되지 않는 살충 성분의 농도(ppm)를 조사한 결과(가상 자료)이다.\n\n'
  '· 물 0.00005 → 플랑크톤 0.04 → 작은 물고기 0.5 → 큰 물고기 2 → 물새 25\n\n'
  '물새 몸속의 농도는 플랑크톤 몸속 농도의 몇 배인가?',
  '625배', ['50배', '125배', '500000배', '12.5배'],
  ['25 ÷ 0.04 = 625이므로 물새의 농도는 플랑크톤의 625배이다.',
   '분해·배출되지 않는 물질은 먹이 사슬을 따라 상위 단계로 갈수록 몸속에 쌓여 농도가 높아지는데, 이를 생물 농축이라고 한다.',
   '500000배는 물새를 플랑크톤이 아니라 물과 비교한 값이다. 생물 농축으로 최상위 포식자가 먼저 피해를 입어 생물다양성이 줄 수 있다.'])

