inner_four = 4 * (side / 2 - 2 * edge) ** 2
assert inner_one == 64 and inner_four == 36
Q(T, 3, '한 변이 10 km인 정사각형 숲이 있다. 숲의 가장자리에서 안쪽으로 1 km까지는 소음·빛·바람 등의 영향(가장자리 효과)을 받아 숲 안쪽에 사는 생물이 살기 어렵다고 한다(가상 조건). 이 숲의 한가운데를 가로와 세로로 지나는 도로가 나서 숲이 한 변 5 km인 정사각형 4개로 나뉘었다면, 가장자리 효과를 받지 않는 숲 안쪽 서식지 면적의 합은? (단, 도로의 폭은 무시한다.)',
  '36 km²', ['64 km²', '9 km²', '81 km²', '100 km²'],
  ['나뉘기 전 안쪽 서식지는 한 변 10 − 2 = 8 km인 정사각형으로 64 km²이다.',
   '나뉜 뒤에는 조각마다 한 변 5 − 2 = 3 km인 정사각형 9 km²가 남으므로 합은 4 × 9 = 36 km²이다.',
   '숲 전체 면적(100 km²)은 거의 그대로여도 안쪽 서식지는 64 → 36 km²로 크게 줄어든다. 64 km²는 나뉘기 전의 값이다.'])

Q(T, 3, '기후 변화에 따른 서식지 변화에 대한 설명으로 옳지 않은 것은?',
  '해수면이 높아져도 해안 습지는 언제나 내륙 쪽으로 자유롭게 옮겨 갈 수 있으므로 면적이 줄지 않는다.',
  ['산꼭대기 부근에 사는 생물은 기온이 오르면 더 올라갈 곳이 없어 서식지가 좁아진다.',
   '기온이 오르면 많은 생물의 분포 범위가 고위도나 높은 곳으로 옮겨 간다.',
   '서식지가 단편화되어 있으면 생물이 알맞은 기후를 찾아 이동하기 어렵다.',
   '바닷물의 온도가 오르면 물고기의 분포 해역이 바뀔 수 있다.'],
  ['해안 습지 뒤쪽에 제방·도로·건물이 있으면 습지가 내륙으로 옮겨 가지 못해, 해수면이 오르면 습지가 물에 잠겨 면적이 줄 수 있다.',
   '생물이 기후 변화에 맞춰 이동하려면 이어진 서식지가 필요하므로 서식지 단편화는 기후 변화의 피해를 키운다.',
   '나머지 설명은 모두 옳다.'])

