Q(T, 4, '어느 나비 종이 사는 지역의 북쪽 경계(북방 한계선)를 조사한 결과(가상 자료)이다.\n\n'
  '· 1998년: 북위 35.0°\n· 2020년: 북위 36.0°\n· 같은 기간 이 지역의 연평균 기온은 꾸준히 올랐다. (단, 위도 1°의 거리는 약 110 km로 한다.)\n\n이 자료에 대한 해석으로 옳은 것은?',
  '이 나비의 북방 한계선은 1년에 평균 약 5 km씩 북쪽으로 옮겨 갔다.',
  ['이 나비의 북방 한계선은 1년에 평균 약 50 km씩 북쪽으로 옮겨 갔다.',
   '이 나비의 북방 한계선은 1년에 평균 약 110 km씩 북쪽으로 옮겨 갔다.',
   '이 나비의 북방 한계선은 1년에 평균 약 0.5 km씩 북쪽으로 옮겨 갔다.',
   '이 나비의 북방 한계선은 남쪽으로 옮겨 갔다.'],
  ['북방 한계선은 위도 1.0° 북쪽으로, 곧 약 110 km 옮겨 갔다.',
   '이동에 걸린 시간은 2020 − 1998 = 22년이므로 1년에 110 ÷ 22 = 5 km씩 옮겨 갔다.',
   '기온 상승에 따라 따뜻한 곳에 사는 생물의 분포가 북쪽으로 넓어진 사례로 해석할 수 있다.'])

site = {'P': (21, 1200), 'Q': (17, 1100), 'R': (20, 900)}
fit = lambda t, p: 18 <= t <= 22 and p >= 1000
now = [k for k, (t, p) in site.items() if fit(t, p)]
fut = [k for k, (t, p) in site.items() if fit(t + 2, p)]
assert now == ['P'] and fut == ['Q']
G(T, 5, '어느 곤충 Y는 7월 평균 기온이 18~22 ℃이고 연 강수량이 1000 mm 이상인 곳에서만 살 수 있다(가상 자료). 세 지역의 현재 자료와 2050년 예상은 다음과 같다.\n\n'
  '· P: 7월 평균 기온 21 ℃, 연 강수량 1200 mm\n· Q: 7월 평균 기온 17 ℃, 연 강수량 1100 mm\n· R: 7월 평균 기온 20 ℃, 연 강수량 900 mm\n'
  '· 2050년에는 세 지역의 7월 평균 기온이 모두 2 ℃ 오르고, 강수량은 변하지 않는다고 가정한다.',
  [('현재 Y가 살 수 있는 곳은 P와 R이다.', False,
    'R은 기온 조건은 맞지만 강수량(900 mm)이 1000 mm에 못 미친다. 현재 살 수 있는 곳은 P뿐이다'),
   ('2050년에는 Q가 Y가 살 수 있는 곳이 된다.', True,
    'Q는 17 + 2 = 19 ℃가 되고 강수량 1100 mm이므로 두 조건을 모두 만족한다'),
   ('2050년에 Y가 살 수 있는 지역의 수는 현재와 같다.', True,
    'P는 23 ℃가 되어 살 수 없고, R은 22 ℃로 기온은 맞지만 강수량이 부족하다. 2050년에는 Q 한 곳으로, 현재(P 한 곳)와 수가 같다')],
  pre=['기온 조건과 강수량 조건을 모두 만족해야 살 수 있다.'])

