Q(T, 2, '어느 나라의 소득 계층별 1인당 연간 탄소 배출량(가상 자료)이다.\n\n'
  '· 소득 상위 10 %: 1인당 30 t\n· 소득 중간 40 %: 1인당 5 t\n· 소득 하위 50 %: 1인당 2 t\n\n이 나라 전체 배출량 가운데 소득 상위 10 %가 차지하는 비율은?',
  '50 %', ['10 %', '30 %', '75 %', '약 17 %'],
  ['인구를 100명으로 두면 상위 10명이 10 × 30 = 300 t, 중간 40명이 40 × 5 = 200 t, 하위 50명이 50 × 2 = 100 t을 배출하여 모두 600 t이다.',
   '상위 10 %의 비율은 300 ÷ 600 × 100 = 50 %이다.',
   '10 %는 인구 비율을 그대로 쓴 값이고, 약 17 %는 하위 50 %가 차지하는 비율이다. 인구의 10 %가 배출의 절반을 차지하는 불평등이 나타난다.'])

