Q(T, 3, '「선진국은 산업화 과정에서 온실 기체를 오랫동안 많이 배출했으므로 더 큰 감축 책임을 져야 한다.」라는 주장의 근거로 가장 알맞은 자료는?',
  '나라별 누적 배출량(과거부터 배출한 양의 합)',
  ['나라별 올해의 배출 증가율', '나라별 국토 면적', '나라별 인구 증가율', '나라별 재생 에너지 잠재량'],
  ['이 주장은 「과거부터 오랫동안 많이 배출했다」는 역사적 책임을 근거로 삼는다.',
   '대기 중 온실 기체는 오래 머물며 쌓이므로, 과거부터 배출한 양을 모두 더한 누적 배출량이 이 주장을 뒷받침하는 자료이다.',
   '올해의 배출 증가율이나 국토 면적·인구 증가율은 역사적 책임을 보여 주지 못한다.'])

E(T, 4, '다음 자료(가상 자료)를 보고 물음에 답하시오.\n\n'
  '· A국(선진국): 1인당 연간 배출량 15 t, 산업화 이후 누적 배출량이 세계에서 가장 많은 편이며, 해안에 대규모 방조제를 갖추고 있다.\n'
  '· B국(낮은 섬나라): 1인당 연간 배출량 1 t, 국토 대부분이 해발 2 m 이하이며, 해수면 상승으로 마실 물에 바닷물이 스며들고 있다.\n\n'
  '두 나라의 사례에서 나타나는 기후 불평등의 모습을 ① 원인에 대한 책임과 피해의 크기, ② 피해에 대응하는 능력의 두 측면에서 서술하고, 이를 줄이기 위한 방안을 한 가지 제시하시오.',
  '① 책임과 피해: A국은 1인당 배출량과 누적 배출량이 많아 기후 변화에 대한 책임이 크지만, B국은 배출량이 매우 적은데도 해수면 상승으로 국토와 식수가 위협받는 큰 피해를 입고 있다. 곧 원인을 제공한 정도와 피해의 크기가 서로 어긋난다. '
  '② 대응 능력: A국은 방조제 같은 적응 시설을 갖출 돈과 기술이 있지만, B국은 그런 능력이 부족해 같은 기후 변화에도 피해가 더 커진다. '
  '방안: 역사적 책임이 큰 선진국이 기후 기금 등을 통해 취약국의 적응 시설과 기술을 지원하고, 이미 입은 손실과 피해를 보상하는 국제 협력을 강화한다.',
  ['[채점 기준] ① 책임(배출량)과 피해의 크기가 어긋난다는 점을 두 나라의 자료를 근거로 서술하면 4점.',
   '② 적응에 필요한 돈·기술 등 대응 능력의 차이를 서술하면 3점.',
   '③ 선진국의 재정·기술 지원, 손실과 피해 보상, 취약국 적응 지원 등 실현 가능한 방안을 한 가지 제시하면 3점.',
   '자료에 없는 수치를 지어내거나 한 측면만 쓰면 해당 항목의 점수를 주지 않는다.'])

E(T, 5, '다음은 우리나라 어느 도시의 폭염 피해에 대한 자료(가상 자료)이다.\n\n'
  '· 지난여름 온열 질환자의 약 절반이 65세 이상이었고, 야외 작업 중 발생한 경우가 많았다.\n'
  '· 냉방 기기가 없는 좁은 주택(쪽방 등)이 모인 지역은 밤에도 실내 기온이 30 ℃ 가까이 유지되었다.\n'
  '· 도심의 녹지가 적은 지역일수록 주변보다 기온이 높았다.\n\n'
  '「기후 위기의 피해는 모두에게 똑같이 나타난다.」라는 주장을 위 자료를 근거로 비판하고, 이 도시가 추진할 수 있는 정책을 두 가지 제안하는 글을 400자 안팎으로 쓰시오.',
  '위 주장은 옳지 않다. 자료를 보면 지난여름 온열 질환자의 절반가량이 65세 이상이었고 야외 작업 중 발생한 경우가 많았다. 이는 몸이 약한 노인과 햇볕 아래에서 일해야 하는 노동자가 폭염에 더 많이 노출되고 더 쉽게 피해를 입는다는 것을 보여 준다. '
  '또 냉방 기기가 없는 좁은 주택이 모인 지역은 밤에도 실내가 30 ℃ 가까이 유지되어, 경제적 여건에 따라 더위를 피할 수 있는 정도가 다르다. 녹지가 적은 지역의 기온이 더 높다는 점은 사는 곳의 환경에 따라서도 피해가 달라짐을 뜻한다. '
  '따라서 기후 위기의 피해는 나이·직업·소득·거주 환경에 따라 불평등하게 나타난다. '
  '이 도시는 첫째, 폭염 특보 때 야외 작업 시간을 조정하고 휴식 시간과 그늘 쉼터를 보장하는 제도를 마련해야 한다. 둘째, 취약 가구에 냉방비와 냉방 기기를 지원하고, 녹지가 부족한 지역에 나무를 심고 무더위 쉼터를 늘려야 한다.',
  ['[채점 기준] ① 자료의 세 가지 근거(연령·야외 노동, 주거 여건, 녹지) 가운데 두 가지 이상을 들어 주장을 비판하면 4점.',
   '② 피해가 사회적 조건에 따라 불평등하게 나타난다는 결론을 분명히 쓰면 2점.',
   '③ 자료와 연결되는 실현 가능한 정책을 두 가지 제안하면 각 2점(모두 4점).',
   '400자 안팎의 완성된 글이 아니거나 근거 없이 주장만 쓰면 감점한다.'])

