# Ⅲ. 기후위기에 대응하는 우리의 노력 — 기후위기 완화와 적응
# ══════════════════════════════════════════════════════════════
T = 'u2m0s0t0'  # 탄소중립 개념 설명
Q(T, 1, '인간 활동으로 배출하는 온실 기체의 양에서 숲 등의 흡수량과 기술로 제거하는 양을 빼서 순배출량을 0으로 만드는 것을 무엇이라고 하는가?',
  '탄소 중립(넷제로)', ['탄소 발자국', '배출권 거래제', '탄소 포집', '에너지 효율'],
  ['탄소 중립은 배출량과 흡수·제거량을 같게 하여 순배출량을 0으로 만드는 것으로, 넷제로(Net-Zero)라고도 한다.',
   '배출을 줄이는 노력과 흡수·제거를 늘리는 노력이 함께 필요하다.',
   '탄소 발자국은 배출한 온실 기체의 총량, 탄소 포집은 배출된 이산화 탄소를 모으는 기술로 탄소 중립을 이루는 수단 가운데 하나이다.'])

eq(6.0 - 0.4 - 0.2, 5.4)
Q(T, 2, '어느 나라의 1년 온실 기체 배출량이 6.0억 t, 산림의 흡수량이 0.4억 t, 탄소 포집·저장 기술로 제거한 양이 0.2억 t이라면(가상 자료), 이 나라의 순배출량은?',
  '5.4억 t', ['6.6억 t', '6.0억 t', '5.8억 t', '5.6억 t'],
  ['순배출량 = 배출량 − 흡수량 − 제거량이다.',
   '6.0 − 0.4 − 0.2 = 5.4억 t이다.',
   '6.6억 t은 흡수·제거량을 더한 값이고, 5.8억 t과 5.6억 t은 제거량이나 흡수량 가운데 하나만 뺀 값이다. 탄소 중립까지는 5.4억 t을 더 줄여야 한다.'])

Q(T, 3, '탄소 중립에 대한 설명으로 옳지 않은 것은?',
  '탄소 중립은 배출량 자체를 0으로 만드는 것이므로 숲의 흡수나 탄소 포집은 고려하지 않는다.',
  ['탄소 중립은 넷제로라고도 부른다.',
   '탄소 중립을 이루려면 배출을 줄이는 노력과 흡수를 늘리는 노력이 함께 필요하다.',
   '우리나라는 2050년까지 탄소 중립을 이루겠다는 목표를 세웠다.',
   '재생 에너지 확대와 에너지 효율 향상은 배출을 줄이는 방법이다.'],
  ['탄소 중립은 배출량에서 흡수량과 제거량을 뺀 순배출량을 0으로 만드는 것이다.',
   '따라서 숲의 흡수와 탄소 포집 같은 제거도 함께 고려한다.',
   '나머지 설명은 모두 옳다.'])

eq(7.0 * (1 - 0.40), 4.2)
Q(T, 3, '우리나라는 2030년까지 온실 기체 배출량을 2018년 배출량에 비해 40 % 줄이는 목표를 세웠다. 계산을 쉽게 하려고 2018년 배출량을 7.0억 t이라고 할 때, 2030년의 목표 배출량은?',
  '4.2억 t', ['2.8억 t', '6.6억 t', '5.6억 t', '3.0억 t'],
  ['40 %를 줄이면 2018년 배출량의 60 %가 남는다.',
   '7.0 × 0.6 = 4.2억 t이 2030년의 목표 배출량이다.',
   '2.8억 t은 줄여야 할 양(7.0 × 0.4)을 답으로 쓴 값이고, 6.6억 t은 40 %가 아니라 0.4억 t을 뺀 값이며, 5.6억 t은 20 %를 줄인 값이다.'])

co2_t, per_tree, per_ha = 200, 10, 1000
trees = co2_t * 1000 / per_tree
assert trees == 20000 and trees / per_ha == 20
Q(T, 4, '어느 학교가 1년 동안 배출하는 이산화 탄소는 200 t이다. 나무 한 그루가 1년에 이산화 탄소 10 kg을 흡수하고, 숲 1 ha에 나무 1000그루가 자란다고 할 때(가상 자료), 이 학교의 배출량을 나무의 흡수만으로 모두 상쇄하려면 필요한 숲의 넓이는?',
  '20 ha', ['2 ha', '200 ha', '0.2 ha', '20000 ha'],
  ['200 t = 200000 kg이므로 필요한 나무는 200000 ÷ 10 = 20000그루이다.',
   '숲 1 ha에 1000그루가 자라므로 필요한 숲의 넓이는 20000 ÷ 1000 = 20 ha이다.',
   '0.2 ha나 200 ha는 t과 kg의 환산을 잘못한 값이고, 20000 ha는 나무의 수를 넓이로 착각한 값이다. 흡수만으로 상쇄하려면 매우 넓은 숲이 필요하므로 배출 자체를 줄이는 노력이 중요하다.'])

em0, sink, cut = 5.0, 1.0, 0.4
n = (em0 - sink) / cut
eq(n, 10)
G(T, 5, '어느 나라의 현재 배출량은 5억 t, 흡수량은 1억 t이다(가상 자료). 이 나라는 해마다 배출량을 0.4억 t씩 줄이고, 흡수량은 그대로 유지할 계획이다.',
  [('탄소 중립을 위해서는 화석 연료 사용을 줄이는 것과 함께 흡수원을 지키고 늘리는 노력이 필요하다.', True,
    '탄소 중립은 배출 감축과 흡수 확대를 함께 추진해야 이룰 수 있다'),
   ('배출량이 흡수량보다 많은 상태를 「탄소 네거티브」라고 한다.', False,
    '탄소 네거티브는 흡수·제거량이 배출량보다 많아 순배출량이 0보다 작은 상태이다'),
   ('이 계획대로라면 10년 뒤에 탄소 중립에 이른다.', True,
    '배출량이 흡수량과 같은 1억 t이 되려면 4억 t을 줄여야 하므로 4 ÷ 0.4 = 10년이 걸린다')])

T = 'u2m0s0t1'  # 재생에너지 사례 분석
Q(T, 1, '다음 중 재생 에너지가 아닌 것은?',
  '천연가스', ['태양광', '풍력', '지열', '조력'],
  ['재생 에너지는 햇빛·바람·지열·조수·물의 흐름처럼 자연에서 계속 다시 얻을 수 있는 에너지이다.',
   '천연가스는 땅속에 묻힌 화석 연료로, 쓰면 없어지고 태울 때 이산화 탄소를 배출한다.',
   '태양광·풍력·지열·조력은 모두 재생 에너지이다.'])

Q(T, 2, '밀물과 썰물 때 생기는 바닷물 높이의 차이를 이용하여 전기를 만드는 발전 방식으로, 우리나라 시화호에도 발전소가 있는 것은?',
  '조력 발전', ['파력 발전', '지열 발전', '댐식 수력 발전', '해상 풍력 발전'],
  ['조력 발전은 밀물과 썰물의 수위 차이(조차)를 이용해 수차를 돌려 전기를 만든다.',
   '조차가 큰 바다에서 유리하며, 우리나라에는 시화호 조력 발전소가 있다.',
   '파력 발전은 파도의 움직임, 지열 발전은 땅속의 열, 해상 풍력 발전은 바다 위의 바람을 이용한다.'])

Q(T, 3, '재생 에너지에 대한 설명으로 옳지 않은 것은?',
  '태양광 발전은 날씨와 시간에 관계없이 언제나 일정한 양의 전기를 만든다.',
  ['태양광·풍력 발전은 발전 과정에서 온실 기체를 거의 배출하지 않는다.',
   '대규모 태양광·풍력 발전 시설은 넓은 부지가 필요할 수 있다.',
   '남는 전기를 저장했다가 필요할 때 쓰는 에너지 저장 장치(ESS)가 재생 에너지 보급에 도움이 된다.',
   '지열 발전은 태양광 발전보다 날씨의 영향을 적게 받는다.'],
  ['태양광 발전은 밤에는 전기를 만들지 못하고, 흐리거나 비가 오면 발전량이 줄어든다.',
   '이처럼 발전량이 날씨와 시간에 따라 들쭉날쭉한 것을 간헐성이라고 하며, 이를 보완하려고 에너지 저장 장치를 쓴다.',
   '나머지 설명은 모두 옳다.'])

kwh = 3 * 4 * 30
eq(kwh, 360); eq(kwh * 0.5, 180); eq(3 * 4 * 365 * 0.5, 2190)
Q(T, 3, '어느 가정에서 설비 용량 3 kW인 태양광 패널을 설치하였다. 이 패널이 하루 평균 4시간 동안 설비 용량만큼 발전하고, 이 전기가 화력 발전 전기를 대신하여 1 kWh당 이산화 탄소 0.5 kg의 배출을 줄인다고 할 때(가상 자료), 30일 동안 줄이는 이산화 탄소의 양은?',
  '180 kg', ['360 kg', '6 kg', '12 kg', '2190 kg'],
  ['하루 발전량은 3 kW × 4 h = 12 kWh이고, 30일 동안 12 × 30 = 360 kWh이다.',
   '줄이는 이산화 탄소는 360 × 0.5 = 180 kg이다.',
   '360 kg은 배출 계수 0.5를 곱하지 않은 값, 6 kg은 하루치, 2190 kg은 1년(365일)치를 계산한 값이다.'])

hrs = [6, 9, 12, 15, 18, 21]; pv = [0, 40, 100, 50, 5, 0]; dm = [60, 70, 80, 75, 90, 70]
