Q(T, 4, '어느 지역의 하루 동안 시각별 전력 수요와 태양광 발전량(가상 자료, 단위: MW)이다.\n\n'
  '· 시각: 06시, 09시, 12시, 15시, 18시, 21시\n· 전력 수요: 60, 70, 80, 75, 90, 70\n· 태양광 발전량: 0, 40, 100, 50, 5, 0\n\n이 자료에 대한 해석으로 옳은 것은?',
  '12시에는 태양광 발전량이 수요보다 20 MW 많으므로, 남는 전기를 저장해 두었다가 수요가 많은 저녁에 쓰는 방법을 생각할 수 있다.',
  ['전력 수요가 가장 많은 시각에 태양광 발전량도 가장 많다.',
   '태양광 발전만으로 하루 종일 전력 수요를 채울 수 있다.',
   '09시에 태양광으로 채우지 못하는 수요는 20 MW이다.',
   '18시에는 태양광 발전량이 수요보다 많다.'],
  ['12시에는 발전량 100 MW가 수요 80 MW보다 20 MW 많다.',
   '수요가 가장 많은 때는 18시(90 MW)인데 이때 태양광 발전량은 5 MW뿐이어서, 낮에 남는 전기를 저장해 저녁에 쓰는 에너지 저장 장치가 필요하다.',
   '09시에 부족한 수요는 70 − 40 = 30 MW이고, 06시·21시에는 태양광 발전량이 0이다.'])

G(T, 5, '재생 에너지 확대에 따른 효과와 과제에 대하여 학생들이 다음과 같이 평가하였다.',
  [('풍력 발전은 발전 과정에서 온실 기체를 거의 배출하지 않는다.', True,
    '바람의 운동 에너지로 발전기를 돌리므로 연료를 태우지 않는다'),
   ('숲을 베어 내고 대규모 태양광 단지를 지으면 탄소 흡수원이 줄어드는 문제가 생길 수 있다.', True,
    '숲은 이산화 탄소를 흡수하는 탄소 흡수원이므로 입지를 정할 때 생태계에 미치는 영향도 따져야 한다'),
   ('지열 발전은 태양광 발전보다 날씨와 낮밤의 영향을 크게 받는다.', False,
    '지열 발전은 땅속의 열을 이용하므로 날씨와 낮밤의 영향을 거의 받지 않는다')])

T = 'u2m0s0t2'  # 탄소중립 정책 평가
