Q(T, 4, '어느 지역이 검토 중인 세 가지 온실 기체 감축 정책의 자료(가상 자료)이다.\n\n'
  '· 정책 X: 연간 감축량 100만 t, 연간 비용 50억 원\n· 정책 Y: 연간 감축량 40만 t, 연간 비용 8억 원\n· 정책 Z: 연간 감축량 200만 t, 연간 비용 200억 원\n\n1 t을 줄이는 데 드는 비용을 기준으로 평가할 때 옳은 것은?',
  '1 t을 줄이는 데 드는 비용이 가장 적은 정책은 Y이다.',
  ['감축량이 가장 많은 Z가 1 t당 비용도 가장 적다.',
   'X의 1 t당 비용이 세 정책 가운데 가장 적다.',
   'Z의 1 t당 비용은 X의 4배이다.',
   'Y의 1 t당 비용은 X의 절반이다.'],
  ['1 t당 비용은 X가 50억 ÷ 100만 = 5000원, Y가 8억 ÷ 40만 = 2000원, Z가 200억 ÷ 200만 = 10000원이다.',
   '따라서 Y가 가장 적고, Z는 X의 2배, Y는 X의 0.4배이다.',
   '감축량이 많다고 1 t당 비용이 적은 것은 아니므로, 정책을 평가할 때는 감축량과 비용을 함께 보아야 한다.'])

