Q(T, 4, '어느 나라의 2050년 전력 부문에 대한 두 시나리오(가상 자료)이다.\n\n'
  '· 시나리오 P: 전력 수요 6000억 kWh, 1 kWh당 이산화 탄소 배출량 0.10 kg\n'
  '· 시나리오 Q: 전기차·전기 난방이 크게 늘어 전력 수요 8000억 kWh, 1 kWh당 이산화 탄소 배출량 0.05 kg\n\n이에 대한 평가로 옳은 것은?',
  'Q는 P보다 전력 수요가 많지만 1 kWh당 배출량이 절반이어서 전력 부문 배출량이 더 적다.',
  ['P는 전력 수요가 적으므로 Q보다 전력 부문 배출량이 적다.',
   '두 시나리오의 전력 부문 배출량은 같다.',
   'Q의 전력 부문 배출량은 P의 절반이다.',
   '전력 수요가 많아지면 전력 부문 배출량은 반드시 많아진다.'],
  ['P의 배출량은 6000억 × 0.10 kg = 600억 kg = 6000만 t이다.',
   'Q의 배출량은 8000억 × 0.05 kg = 400억 kg = 4000만 t으로 P의 3분의 2이다.',
   '전력 수요가 늘어도 전기를 저탄소로 만들면 배출량이 줄 수 있다. 수송·난방을 전기로 바꾸면 그 부문의 화석 연료 사용도 줄어든다.'])

